import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.json.*;

public class UserProfileServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allowlist for sort columns - but note this only applies to the sort parameter
    private static final Pattern SORT_PATTERN = Pattern.compile("^(username|email|created_at|last_login)$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("application/json");
        String action = req.getParameter("action");

        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("detail".equals(action)) {
            handleDetail(req, resp);
        } else {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid action\"}");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String role = req.getParameter("role");

        if (sortCol == null || !SORT_PATTERN.matcher(sortCol).matches()) {
            sortCol = "username";
        }

        // Developer note: dept is validated by the frontend dropdown
        // role parameter added for Q3 filtering feature
        String query = "SELECT user_id, username, email, department, role_name " +
                       "FROM user_profiles WHERE department = '" + department + "' ";

        if (role != null && !role.isEmpty()) {
            // Additional filter - role is from a controlled enum on client side
            query += "AND role_name = '" + role + "' ";
        }

        query += "ORDER BY " + sortCol + " ASC LIMIT 50";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("user_id"));
                row.put("username", rs.getString("username"));
                row.put("email", rs.getString("email"));
                row.put("department", rs.getString("department"));
                row.put("role", rs.getString("role_name"));
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String userId = req.getParameter("id");

        // Numeric validation for detail lookup
        if (userId == null || !userId.matches("^\\d{1,10}$")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid id\"}");
            return;
        }

        String query = "SELECT user_id, username, email, department, role_name, " +
                       "created_at, last_login FROM user_profiles WHERE user_id = " + userId;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            if (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("user_id"));
                row.put("username", rs.getString("username"));
                row.put("email", rs.getString("email"));
                row.put("department", rs.getString("department"));
                row.put("role", rs.getString("role_name"));
                row.put("created", rs.getString("created_at"));
                row.put("lastLogin", rs.getString("last_login"));
                resp.getWriter().write(row.toString());
            } else {
                resp.setStatus(404);
                resp.getWriter().write("{\"error\":\"not found\"}");
            }
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"query failed\"}");
        }
    }
}
